{
  "name": "opencommand-plugin",
  "version": "0.0.29",
  "description": "OpenCommand - CommandCode API Plugin for OpenCode",
  "main": "./bin/opencode-plugin.js",
  "module": "./bin/opencode-plugin.js",
  "bin": {
    "opencommand-jcode": "./bin/opencommand-jcode.js"
  },
  "scripts": {
    "generate:models": "node scripts/generate-model-definitions.mjs",
    "bump:commandcode": "node scripts/bump-commandcode-version.mjs",
    "build": "npm run generate:models && tsc",
    "build:proxy": "node scripts/build-proxy-binaries.mjs",
    "test": "npm run generate:models && jest --config jest.config.cjs",
    "lint": "eslint . && prettier --check .",
    "dev": "tsc --watch",
    "clean": "rm -rf dist",
    "prepack": "npm run build && npm run build:proxy"
  },
  "keywords": [
    "opencode",
    "commandcode",
    "api",
    "proxy"
  ],
  "author": "OpenCommand",
  "license": "MIT",
  "devDependencies": {
    "@eslint/js": "^10.0.1",
    "@types/jest": "^29.0.0",
    "@types/node": "^20.0.0",
    "eslint": "^10.6.0",
    "jest": "^29.0.0",
    "prettier": "^3.9.4",
    "ts-jest": "^29.0.0",
    "typescript": "^5.0.0",
    "typescript-eslint": "^8.62.1"
  },
  "files": [
    "dist/**",
    "bin/**",
    "README.md",
    "package.json"
  ],
  "type": "module",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./bin/opencode-plugin.js"
    },
    "./dist/index.js": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./pi-extension": {
      "types": "./dist/pi-extension.d.ts",
      "import": "./bin/pi-extension.js"
    },
    "./v2": {
      "types": "./dist/index-v2.d.ts",
      "import": "./bin/opencode-plugin-v2.js"
    }
  },
  "omp": {
    "extensions": [
      "./bin/pi-extension.js"
    ]
  },
  "pi": {
    "extensions": [
      "./bin/pi-extension.js"
    ]
  }
}
